			if(ent:IsClient() and e.self:CalculateDistance(ent:GetX(), ent:GetY(), ent:GetZ()) >= 100) then
			  local currclient=ent:CastToClient();
				--e.self:Shout("You will not evade me " .. currclient:GetName()) keeper doesnt shout
